--
-- TOC entry 1118 (class 1255 OID 25705)
-- Name: notify_table_change(); Type: FUNCTION; Schema: 26a05b633aaeaec5; Owner: postgres
--

CREATE FUNCTION "26a05b633aaeaec5".notify_table_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
  BEGIN
      IF TG_OP = 'INSERT' THEN
          PERFORM pg_notify('event_channel', json_build_object(
              'table', TG_TABLE_NAME,
              'schema', TG_TABLE_SCHEMA,
              'action', TG_OP,
              'data', row_to_json(NEW),
              'timestamp', NOW()
          )::text);
      ELSIF TG_OP = 'UPDATE' AND NEW IS DISTINCT FROM OLD THEN
          PERFORM pg_notify('event_channel', json_build_object(
              'table', TG_TABLE_NAME,
              'schema', TG_TABLE_SCHEMA,
              'action', TG_OP,
              'data', row_to_json(NEW),
              'timestamp', NOW()
          )::text);
      ELSIF TG_OP = 'DELETE' THEN
          PERFORM pg_notify('event_channel', json_build_object(
              'table', TG_TABLE_NAME,
              'schema', TG_TABLE_SCHEMA,
              'action', TG_OP,
              'data', row_to_json(OLD),
              'timestamp', NOW()
          )::text);
      END IF;

      RETURN NEW;
